exp = {1: (10, 500), 2: (11, 700), 3: (12, 900)}
tgt = {1: (10, 500), 2: (11, 770), 3: (12, 900), 4: (13, 5)}

def row_hash(values):
    text = '|'.join(str(v) for v in values)
    return hashlib.sha256(text.encode('utf-8')).hexdigest()

print(sorted(k for k in set(exp) & set(tgt) if row_hash(exp[k]) != row_hash(tgt[k])))

