expected = {1: 100, 2: 250, 3: 75, 4: 900}
target = {1: 100, 2: 205, 4: 900, 7: 30}

def validate(expected, target):
    problems = []
    if len(expected) != len(target):
        problems.append(f"count expected {len(expected)} got {len(target)}")
    se, st = sum(expected.values()), sum(target.values())
    if se != st:
        problems.append(f"sum expected {se} got {st}")
    problems += [f"missing {k}" for k in sorted(set(expected) - set(target))]
    problems += [f"extra {k}" for k in sorted(set(target) - set(expected))]
    problems += [f"changed {k}" for k in sorted(set(expected) & set(target)) if expected[k] != target[k]]
    return problems

for line in validate(expected, target):
    print(line)
if not validate(expected, dict(expected)):
    print('OK')

