import hashlib

source = [(1, '12.5', ' usd'), (2, '3', 'EUR'), (3, '8.25', 'usd')]
target = [(1, 12.5, 'USD'), (2, 3.0, 'EUR'), (3, 8.3, 'USD')]

def canon(row):
    i, amount, cur = row
    return (i, round(float(amount) * 100), cur.strip().upper())

def h(row):
    return hashlib.sha256('|'.join(map(str, canon(row))).encode('utf-8')).hexdigest()

for s, t in zip(source, target):
    print(h(s) == h(t))
